 seen.add(k);ar=d.execute('SELECT source_sha256,content_xml FROM articles WHERE code_id=? AND id=?',k).fetchone();pr=d.execute('SELECT source_sha256,proposed_xml FROM drafts WHERE code_id=? AND source_id=?',k).fetchone();old=s.get('previous_draft');expected=(old['source_sha256'],old['proposed_xml'])if old else None
